epoll splits poll's single call into a setup step and a wait step. An **epoll instance** is a kernel object that you reach through its own file descriptor. The [epoll(7)](https://man7.org/linux/man-pages/man7/epoll.7.html) page describes it as a container for two lists:

- the **interest list**: every descriptor you registered, with the events you want;
- the **ready list**: references to the subset that are ready for I/O, filled in by the kernel as I/O happens.

blocks.code:
int ep = epoll_create1(0);
struct epoll_event ev = { .events = EPOLLIN };
ev.data.ptr = conn;            /* returned verbatim by epoll_wait */
epoll_ctl(ep, EPOLL_CTL_ADD, conn->fd, &ev);

struct epoll_event evs[64];
int n = epoll_wait(ep, evs, 64, timeout_ms);
for (int i = 0; i < n; i++) {
    struct conn *c = evs[i].data.ptr;
    if (evs[i].events & (EPOLLERR | EPOLLHUP)) close_conn(c);
    else if (evs[i].events & EPOLLIN) on_readable(c);
}

int ep = epoll_create1(0);
struct epoll_event ev = { .events = EPOLLIN, .data.fd = lfd };
epoll_ctl(ep, EPOLL_CTL_ADD, lfd, &ev);
struct epoll_event evs[64];
for (;;) {
    int n = epoll_wait(ep, evs, 64, -1);
    for (int i = 0; i < n; i++) {
        int fd = evs[i].data.fd;
        if (fd == lfd) {
            int c = accept4(lfd, NULL, NULL, SOCK_NONBLOCK);
            ev.events = EPOLLIN; ev.data.fd = c;
            epoll_ctl(ep, EPOLL_CTL_ADD, c, &ev);
        } else {
            ssize_t r = read(fd, buf, sizeof buf);
            if (r == 0) { close(fd); continue; }
            handle(fd, buf, r);
        }
    }
}

// EPOLLET: keep reading until the kernel says EAGAIN
for (;;) {
    ssize_t r = read(fd, buf, 1024);
    if (r > 0) { consume(buf, r); continue; }
    if (r == 0) { close_conn(fd); break; }      // peer closed
    if (errno == EAGAIN || errno == EWOULDBLOCK) break;
    if (errno == EINTR) continue;
    close_conn(fd); break;                      // real error
}
